python3 << 'EOF'
import csv
import json
from collections import defaultdict

data = []
with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        data.append(row)

cities_data = defaultdict(list)
for row in data:
    cities_data[row['city']].append(row)

results = {}

for city, rows in cities_data.items():
    total = len(rows)

    # Price stats
    prices = []
    for row in rows:
        try:
            p = float(row['price'])
            if p > 0 and p < 10000:
                prices.append(p)
        except (ValueError, TypeError):
            pass

    if prices:
        ps = sorted(prices)
        n = len(ps)
        if n % 2 == 1:
            median_price = ps[n//2]
        else:
            median_price = (ps[n//2-1] + ps[n//2]) / 2
        mean_price = sum(prices) / n
    else:
        median_price = mean_price = 0

    # Room type breakdown
    room_counts = defaultdict(int)
    for row in rows:
        room_counts[row['room_type']] += 1

    entire_home = room_counts.get('Entire home/apt', 0)
    private_room = room_counts.get('Private room', 0)
    shared_room = room_counts.get('Shared room', 0)
    hotel_room = room_counts.get('Hotel room', 0)

    # Professional host share (>= 5 listings)
    prof_host = sum(1 for row in rows if int(row.get('calculated_host_listings_count', 0) or 0) >= 5)

    # Reviews per month
    rpm_vals = []
    for row in rows:
        try:
            v = float(row['reviews_per_month'])
            if v > 0:
                rpm_vals.append(v)
        except (ValueError, TypeError):
            pass
    avg_rpm = sum(rpm_vals)/len(rpm_vals) if rpm_vals else 0

    # Availability
    avail_vals = []
    for row in rows:
        try:
            v = int(row['availability_365'])
            avail_vals.append(v)
        except (ValueError, TypeError):
            pass
    avg_avail = sum(avail_vals)/len(avail_vals) if avail_vals else 0

    # Minimum nights
    min_nights = []
    for row in rows:
        try:
            v = int(row['minimum_nights'])
            if v > 0 and v <= 365:
                min_nights.append(v)
        except (ValueError, TypeError):
            pass
    avg_min_nights = sum(min_nights)/len(min_nights) if min_nights else 0
    mn_sorted = sorted(min_nights)
    median_min_nights = mn_sorted[len(mn_sorted)//2] if mn_sorted else 0

    # Price by room type
    price_by_room = {}
    for rt in ['Entire home/apt', 'Private room', 'Hotel room']:
        rt_prices = []
        for row in rows:
            if row['room_type'] == rt:
                try:
                    p = float(row['price'])
                    if p > 0 and p < 10000:
                        rt_prices.append(p)
                except (ValueError, TypeError):
                    pass
        if rt_prices:
            rts = sorted(rt_prices)
            rn = len(rts)
            rt_median = rts[rn//2] if rn % 2 == 1 else (rts[rn//2-1] + rts[rn//2]) / 2
            price_by_room[rt] = {'median': round(rt_median, 1), 'mean': round(sum(rt_prices)/len(rt_prices), 1), 'count': len(rt_prices)}

    # LTM reviews
    ltm_vals = []
    for row in rows:
        try:
            v = int(row['number_of_reviews_ltm'])
            ltm_vals.append(v)
        except (ValueError, TypeError):
            pass
    avg_ltm = sum(ltm_vals)/len(ltm_vals) if ltm_vals else 0

    listings_with_reviews = sum(1 for row in rows if int(row.get('number_of_reviews', 0) or 0) > 0)

    results[city] = {
        'total_listings': total,
        'listings_with_price': len(prices),
        'median_price': round(median_price, 1),
        'mean_price': round(mean_price, 1),
        'price_by_room': price_by_room,
        'room_counts': dict(room_counts),
        'entire_home_share': round(entire_home/total*100, 1),
        'private_room_share': round(private_room/total*100, 1),
        'shared_room_share': round(shared_room/total*100, 1),
        'hotel_room_share': round(hotel_room/total*100, 1),
        'prof_host_count': prof_host,
        'prof_host_share': round(prof_host/total*100, 1),
        'avg_reviews_per_month': round(avg_rpm, 2),
        'avg_availability_365': round(avg_avail, 1),
        'avg_min_nights': round(avg_min_nights, 1),
        'median_min_nights': median_min_nights,
        'avg_reviews_ltm': round(avg_ltm, 2),
        'listings_with_reviews': listings_with_reviews,
        'review_rate': round(listings_with_reviews/total*100, 1)
    }

print(json.dumps(results, indent=2))
EOF

